import React, {useState, useEffect} from 'react'


export default function Filters({setFilter, categories, filter}){

    return(
        <div className="filters">
            {
                categories.map((category,index)=>(
                    <button
                        key={index}
                        className={`filter-btn ${filter?.category === category || (category === 'All' && !filter) ? 'active' : ''}`}
                        onClick={()=> category === 'All' ? setFilter(null) : setFilter({category})}
                    >
                        {category}
                    </button>
                ))
            }
        </div>
    )
}
